/* ---------------------- BASE OPÉRATIONNELLE GSM ---------------------- */
/*
 * Cette API contient uniquement les données métier / opérationnelles :
 * clients, portefeuilles, allocations, expositions devises, flux financiers
 * et Cession_Retrait. Les données de marché restent dans leur source séparée.
 */
const GSM_OPERATIONAL_API =
  import.meta?.env?.VITE_GSM_API_URL ||
  (typeof process !== 'undefined'
    ? process?.env?.NEXT_PUBLIC_GSM_API_URL
    : null) ||
  'http://127.0.0.1:8001';

const gsmOperationalUrl = (path = '') =>
  `${GSM_OPERATIONAL_API}${path.startsWith('/') ? path : `/${path}`}`;

const gsmOperationalRequest = async (
  path,
  { method = 'GET', body = null, adminKey = null } = {}
) => {
  const headers = {
    Accept: 'application/json',
  };

  if (body !== null) {
    headers['Content-Type'] = 'application/json';
  }
  if (adminKey) {
    headers['X-Admin-Key'] = adminKey;
  }

  const response = await fetch(gsmOperationalUrl(path), {
    method,
    headers,
    body: body === null ? undefined : JSON.stringify(body),
    cache: 'no-store',
  });

  const raw = await response.text();
  let payload = null;
  try {
    payload = raw ? JSON.parse(raw) : null;
  } catch {
    payload = raw;
  }

  if (!response.ok) {
    const detail =
      payload?.detail ||
      (typeof payload === 'string' ? payload : null) ||
      `Erreur HTTP ${response.status}`;
    throw new Error(detail);
  }

  return payload;
};

const loadGsmOperationalSnapshot = () =>
  gsmOperationalRequest('/api/snapshot');

const requestGsmAdminAccess = (code) =>
  gsmOperationalRequest('/api/v1/admin-access/', {
    method: 'POST',
    body: { code },
  });

const GSM_OPERATIONAL_WRITE_KEY_STORAGE =
  'opcvm-gsm-operational-admin-key-session';

const getGsmOperationalWriteKey = () => {
  if (typeof window === 'undefined') return '';
  return window.sessionStorage.getItem(
    GSM_OPERATIONAL_WRITE_KEY_STORAGE
  ) || '';
};

const setGsmOperationalWriteKey = (value) => {
  if (typeof window === 'undefined') return;
  if (value) {
    window.sessionStorage.setItem(
      GSM_OPERATIONAL_WRITE_KEY_STORAGE,
      value
    );
  } else {
    window.sessionStorage.removeItem(
      GSM_OPERATIONAL_WRITE_KEY_STORAGE
    );
  }
};
