function Documentation({ mode = 'gestionnaire' }) {
  return (
    <div className="space-y-5">
      {mode === 'client' ? (
        <ClientBreadcrumb items={['Espace Client', 'Documentation']} />
      ) : (
        <Breadcrumb items={['Accueil', 'Documentation']} />
      )}

      <div className="flex items-start justify-between gap-4 flex-wrap">
        <div>
          <Eyebrow>Centre documentaire</Eyebrow>
          <h2
            className="text-xl font-bold"
            style={{ ...F_DISPLAY, color: C.ink }}
          >
            Documentation du logiciel OPCVM GSM
          </h2>
          <div className="text-xs mt-1 max-w-3xl" style={{ color: C.sub }}>
            Retrouvez ici le guide d'utilisation destiné aux utilisateurs
            Gestion sous mandat et Gestion libre, ainsi que les documents
            techniques de référence. Chaque document peut être consulté dans le
            navigateur ou téléchargé localement.
          </div>
        </div>
        <Badge tone="navy">
          {GSM_DOCUMENTATION.length} documents disponibles
        </Badge>
      </div>

      <div className="grid grid-cols-3 gap-4">
        {[
          {
            label: 'Bibliothèque',
            value: 'Guides & architecture',
            detail: 'Utilisation, CRM, données, flux et architecture',
          },
          {
            label: 'Guide utilisateur',
            value: 'Version 2.0',
            detail: 'Mise à jour du 10/11/2026',
          },
          {
            label: 'Format',
            value: 'PDF',
            detail: 'Consultable et téléchargeable',
          },
        ].map((item) => (
          <Card key={item.label} className="p-4">
            <div
              className="text-[10px] uppercase font-semibold"
              style={{ color: C.sub }}
            >
              {item.label}
            </div>
            <div
              className="text-base font-bold mt-1"
              style={{ color: C.ink, ...F_DISPLAY }}
            >
              {item.value}
            </div>
            <div className="text-[10px] mt-1" style={{ color: C.sub }}>
              {item.detail}
            </div>
          </Card>
        ))}
      </div>

      <Card className="p-5">
        <div className="flex items-center justify-between gap-3 flex-wrap mb-4">
          <div>
            <Eyebrow>Documents disponibles</Eyebrow>
            <div className="text-sm font-semibold" style={{ color: C.ink }}>
              Guides d'utilisation et référentiels techniques
            </div>
          </div>
          <Badge tone="gold">Bibliothèque interne</Badge>
        </div>

        <div className="space-y-3">
          {GSM_DOCUMENTATION.map((document) => (
            <div
              key={document.id}
              className="p-4 rounded-2xl border flex items-start justify-between gap-5 flex-wrap"
              style={{ borderColor: C.line, background: '#FAFAFC' }}
            >
              <div className="flex items-start gap-3 min-w-0 flex-1">
                <div
                  className="w-11 h-11 rounded-2xl flex items-center justify-center shrink-0"
                  style={{ background: '#EEF1FF', color: C.indigo }}
                >
                  <BookOpen size={20} />
                </div>

                <div className="min-w-0">
                  <div className="flex items-center gap-2 flex-wrap">
                    <div className="text-sm font-bold" style={{ color: C.ink }}>
                      {document.title}
                    </div>
                    <Badge tone="slate">{document.format}</Badge>
                  </div>
                  <div
                    className="text-[11px] mt-1 leading-relaxed max-w-4xl"
                    style={{ color: C.sub }}
                  >
                    {document.description}
                  </div>
                  <div
                    className="flex items-center gap-4 flex-wrap text-[10px] mt-2"
                    style={{ color: C.sub, ...F_MONO }}
                  >
                    <span>{document.category}</span>
                    <span>Version {document.version}</span>
                    <span>Mise à jour {document.updatedAt}</span>
                  </div>
                </div>
              </div>

              <div className="flex items-center gap-2 shrink-0">
                <button
                  type="button"
                  onClick={() => openDocumentationPdf(document)}
                  className="inline-flex items-center gap-2 px-3 py-2 rounded-xl border text-xs font-semibold"
                  style={{
                    borderColor: C.line,
                    color: C.indigo,
                    background: '#fff',
                    cursor: 'pointer',
                  }}
                >
                  <ExternalLink size={14} />
                  Ouvrir le PDF
                </button>
                <button
                  type="button"
                  onClick={() => downloadDocumentationPdf(document)}
                  className="inline-flex items-center gap-2 px-3 py-2 rounded-xl text-xs font-semibold"
                  style={{
                    background: C.navy,
                    color: '#fff',
                    cursor: 'pointer',
                  }}
                >
                  <Download size={14} />
                  Télécharger
                </button>
              </div>
            </div>
          ))}
        </div>
      </Card>

      <Card className="p-5" style={{ borderColor: C.gold }}>
        <Eyebrow>Disponibilité des documents</Eyebrow>
        <div className="text-sm font-semibold" style={{ color: C.ink }}>
          Documents versionnés et déployables
        </div>
        <div className="text-xs mt-2 leading-relaxed" style={{ color: C.sub }}>
          Les trois PDF de référence sont servis comme assets statiques depuis
          <code
            className="mx-1 px-2 py-1 rounded-lg"
            style={{ background: '#F0F1F5', color: C.navy, ...F_MONO }}
          >
            public/documentation/
          </code>
          . Cette organisation évite d'alourdir le bundle JavaScript avec un PDF
          encodé en Base64 et fonctionne aussi bien en local que sur le domaine,
          à condition de conserver ce dossier lors du build et du déploiement.
        </div>
      </Card>
    </div>
  );
}

